/**
 * @param {number[][]} grid
 * @param {number} health
 * @return {boolean}
 */
var findSafeWalk = function(grid, health) {
    const m = grid.length;
    const n = grid[0].length;

    let stack = [[0, 0, health]];
    const seen = Array.from({ length: m }, () => Array(n).fill(-1));

    while (stack.length > 0) {
        const next = [];

        for (let [r, c, hp] of stack) {
            if (r < 0 || r >= m || c < 0 || c >= n || seen[r][c] >= hp) continue;

            seen[r][c] = hp;

            if (grid[r][c] === 1) {
                hp--;

                if (hp === 0) continue;
            }

            if (r === m - 1 && c === n - 1) {
                return true;
            }

            next.push(
                [r + 1, c, hp],
                [r, c + 1, hp],
                [r - 1, c, hp],
                [r, c - 1, hp],
            );
        }

        stack = next;
    }

    return false;
};
